INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES ("カリン", -416.5, 2, 10130004, 2, 54, "2023/10/31 12:00:00", 10130, "報酬がもらえますよ！\nチェックしてみてください", 190801, "2023/11/18 14:59:59", 4, 0, 0);
INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES ("カリン", -416.5, 1, 10130005, 1, 57, "2023/10/31 12:00:00", 10130, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", 190801, "2023/11/18 14:59:59", 5, 0, 0);
