INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES ("カリン", -363, 1, 10130008, 2, 56, "2023/10/31 12:00:00", 10130, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 190801, "2023/11/18 14:59:59", 3, 1.539, 0);
