INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES ("カリン", -416.5, 2, 20047002, 1, 53, "2023/11/16 15:00:00", 20047, "ミッションをクリアして、\n報酬をゲットしましょう！", 190801, "2030/01/01 14:59:59", 2, 3.099, 0);
INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES ("カリン", -416.5, 2, 20047003, 1, 54, "2023/11/16 15:00:00", 20047, "受け取ることができる\n報酬があるようです\n確認してみてください", 190801, "2030/01/01 14:59:59", 3, 2.801, 0);
INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES ("カリン", -416.5, 2, 20047004, 2, 54, "2023/11/16 15:00:00", 20047, "報酬がもらえますよ！\nチェックしてみてください", 190801, "2030/01/01 14:59:59", 4, 0, 0);
INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES ("カリン", -416.5, 1, 20047005, 1, 57, "2023/11/16 15:00:00", 20047, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", 190801, "2030/01/01 14:59:59", 5, 0, 0);
INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES ("カリン", -363, 2, 20047006, 1, 55, "2023/11/16 15:00:00", 20047, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", 190801, "2030/01/01 14:59:59", 1, 5.506, 0);
INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES ("カリン", -363, 1, 20047007, 2, 55, "2023/11/16 15:00:00", 20047, "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", 190801, "2030/01/01 14:59:59", 2, 1.216, 0);
INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES ("カリン", -363, 1, 20047008, 2, 56, "2023/11/16 15:00:00", 20047, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 190801, "2030/01/01 14:59:59", 3, 1.539, 0);
INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES ("カリン", -363, 1, 20047009, 2, 56, "2023/11/16 15:00:00", 20047, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", 190801, "2030/01/01 14:59:59", 4, 1.875, 0);
